import React from "react";
import { UserContext, UserProvider } from "./UserContext";
import Navbar from "./Navbar";

/**
 * Session 10 Demo Component
 * Shows Navbar consuming UserContext with default value,
 * as well as inside UserProvider with interactive state updates.
 */
function UserContextDemo() {
  return (
    <div style={demoStyles.container}>
      <h2 style={demoStyles.title}>Session 10 - Context API (UserContext)</h2>
      <p style={demoStyles.desc}>
        Demonstrating <code>Navbar</code> consuming <code>UserContext</code> using the <code>useContext</code> hook.
      </p>

      {/* Case 1: Consuming UserContext Default Value directly (Without Provider) */}
      <div style={demoStyles.card}>
        <h4 style={demoStyles.cardTitle}>1. Without Provider (Shows Default Value from createContext)</h4>
        <Navbar />
      </div>

      {/* Case 2: Wrapped in UserProvider (Allows Login/Logout toggle) */}
      <div style={demoStyles.card}>
        <h4 style={demoStyles.cardTitle}>2. Wrapped inside UserProvider (Interactive State)</h4>
        <UserProvider>
          <Navbar />
        </UserProvider>
      </div>
    </div>
  );
}

const demoStyles = {
  container: {
    maxWidth: "900px",
    margin: "30px auto",
    padding: "20px",
    fontFamily: "'Segoe UI', Roboto, sans-serif",
  },
  title: {
    fontSize: "24px",
    fontWeight: "700",
    color: "#0f172a",
    marginBottom: "8px",
  },
  desc: {
    color: "#64748b",
    marginBottom: "24px",
    fontSize: "15px",
  },
  card: {
    backgroundColor: "#f8fafc",
    padding: "20px",
    borderRadius: "14px",
    border: "1px solid #e2e8f0",
    marginBottom: "24px",
  },
  cardTitle: {
    margin: "0 0 12px 0",
    color: "#334155",
    fontSize: "16px",
    fontWeight: "600",
  },
};

export default UserContextDemo;
